<?php
function e($value) { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); }
?>
<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products | LavaLust</title><style>
:root{--ink:#18212b;--muted:#66727a;--paper:#f4f0e8;--white:#fffdf8;--accent:#d85b3f;--line:#d8d0c3}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,var(--paper),#dce7e3);color:var(--ink);font:16px Georgia,serif}.wrap{width:min(1100px,calc(100% - 32px));margin:auto;padding:48px 0}.top{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:28px}h1{margin:0;font-size:clamp(2.2rem,6vw,4.4rem)}.eyebrow{margin:0 0 8px;color:var(--accent);font:700 12px Arial,sans-serif;letter-spacing:.16em;text-transform:uppercase}.actions{display:flex;gap:10px;align-items:center}.button,button{padding:11px 15px;border:0;background:var(--accent);color:#fff;text-decoration:none;font:700 14px Arial,sans-serif;cursor:pointer}.quiet{background:transparent;color:var(--ink);border:1px solid var(--line)}.table{overflow:auto;background:var(--white);border:1px solid var(--line);box-shadow:10px 10px 0 #b8cbc5}table{width:100%;min-width:720px;border-collapse:collapse}th,td{padding:16px;text-align:left;border-bottom:1px solid var(--line)}th{font:700 12px Arial,sans-serif;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}td{vertical-align:top}.description{color:var(--muted);max-width:320px}.actions-cell{white-space:nowrap}.actions-cell a{color:var(--accent);font:700 14px Arial,sans-serif;margin-right:12px}.delete{display:inline;padding:0;background:none;color:#9a3025;font:700 14px Arial,sans-serif}form{display:inline}@media(max-width:650px){.top{align-items:start;flex-direction:column}.actions{width:100%;justify-content:space-between}}
</style></head><body><main class="wrap"><header class="top"><div><p class="eyebrow">Catalogue</p><h1>Products</h1></div><div class="actions"><a class="button" href="<?= e(site_url('products/create')) ?>">Add product</a><form method="post" action="<?= e(site_url('logout')) ?>"><button class="quiet" type="submit">Log out</button></form></div></header><?php if (empty($products)): ?><div class="table"><p style="padding:28px">No products yet. Add your first one.</p></div><?php else: ?><div class="table"><table><thead><tr><th>Name</th><th>Description</th><th>Price</th><th>Quantity</th><th>Actions</th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><strong><?= e($product['product_name']) ?></strong></td><td class="description"><?= e($product['description']) ?></td><td><?= number_format((float) $product['price'], 2) ?></td><td><?= e($product['quantity']) ?></td><td class="actions-cell"><a href="<?= e(site_url('products/edit/' . $product['id'])) ?>">Edit</a><form method="post" action="<?= e(site_url('products/delete/' . $product['id'])) ?>" onsubmit="return confirm('Delete this product?')"><button class="delete" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main></body></html>
